<script setup lang="ts">
import {computed,onBeforeUnmount,onMounted,ref,watch} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import {ElButton,ElSelect,ElOption} from 'element-plus'
import {focusTimer,prepareFocusTimer} from '../services/focusTimer'
import {focusReadBinding,readFocusRecords} from '../services/focusRecordSource'
import {useTasksStore} from '../stores/tasks'
import {useNotesStore} from '../stores/notes'
import {focusDay,focusDuration,focusRange,filterFocusRecords,focusRecordSummary,type FocusRecord} from '../services/focusRecords'
const route=useRoute(),router=useRouter(),tasks=useTasksStore(),notes=useNotesStore()
const today=new Date(),start=new Date(today);start.setDate(start.getDate()-6)
const from=ref(focusDay(start)),to=ref(focusDay(today)),rows=ref<FocusRecord[]>([]),loading=ref(false),error=ref(''),sourceWarning=ref(''),metadataWarning=ref(''),limit=ref(50),kind=ref('all')
const taskUid=ref(typeof route.query.taskUid==='string'?route.query.taskUid:''),noteUid=ref(typeof route.query.noteUid==='string'?route.query.noteUid:'')
const detail=ref<FocusRecord>(),detailDialog=ref<HTMLDialogElement>()
let request=0,disposed=false
const taskOptions=computed(()=>tasks.tasks.filter(item=>!item.deleted).slice().sort((a,b)=>a.title.localeCompare(b.title,'zh-CN')))
const scoped=computed(()=>{try{return filterFocusRecords(rows.value,focusRange(from.value,to.value),taskUid.value,noteUid.value)}catch{return[]}})
const summary=computed(()=>focusRecordSummary(scoped.value))
const filtered=computed(()=>scoped.value.filter(item=>kind.value==='all'||(kind.value==='focus'?item.sessionType==='focus':['short_break','long_break'].includes(item.sessionType))))
const visible=computed(()=>filtered.value.slice(0,limit.value))
const taskTitle=(uid:string)=>tasks.tasks.find(item=>item.uid===uid)?.title||(route.query.taskUid===uid&&typeof route.query.title==='string'?route.query.title:'关联任务信息待同步')
const noteTitle=(uid:string)=>[...notes.notes,...notes.archived].find(item=>item.uid===uid)?.title||(route.query.noteUid===uid&&typeof route.query.title==='string'?route.query.title:'关联笔记信息待同步')
const typeLabel=(type:string)=>({focus:'专注',short_break:'短休息',long_break:'长休息'} as Record<string,string>)[type]||'其他记录'
const statusLabel=(status:string)=>({completed:'已完成',cancelled:'已取消',canceled:'已取消',abandoned:'已中断',interrupted:'已中断',running:'进行中',paused:'已暂停'} as Record<string,string>)[status]||'未完成'
const timestamp=(value:string)=>Number.isFinite(Date.parse(value))?new Date(value).toLocaleString('zh-CN',{year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit'}):'—'
async function load(){
 const binding=focusReadBinding(),token=++request;error.value='';sourceWarning.value='';rows.value=[];loading.value=true
 try{const range=focusRange(from.value,to.value),result=await readFocusRecords(range.from,range.to);if(!disposed&&token===request&&binding===focusReadBinding()){rows.value=result.items;sourceWarning.value=result.localOnly?'云端记录暂不可用，当前仅显示本机记录；联网后可刷新。':''}}
 catch(source){if(!disposed&&token===request&&binding===focusReadBinding())error.value=source instanceof Error?source.message:'专注记录加载失败'}
 finally{if(!disposed&&token===request)loading.value=false}
}
function quickRange(days:number){const end=new Date(),begin=new Date(end);begin.setDate(begin.getDate()-days+1);from.value=focusDay(begin);to.value=focusDay(end)}
function openNote(uid:string){void router.push({path:'/notes',query:{note:uid}})}
function openTask(uid:string){void router.push({path:'/tasks',query:{task:uid}})}
function showDetail(item:FocusRecord){detail.value=item;detailDialog.value?.showModal()}
function closeDetail(){detailDialog.value?.close();detail.value=undefined}
function refresh(){closeDetail();void load()}
function scopeChanged(){closeDetail();rows.value=[];metadataWarning.value='';taskUid.value='';noteUid.value='';const {taskUid:_task,noteUid:_note,title:_title,...query}=route.query;void router.replace({query});void load()}
watch([from,to],load,{immediate:true})
watch([from,to,taskUid,noteUid,kind],()=>{limit.value=50;closeDetail()})
watch(()=>[route.query.taskUid,route.query.noteUid],()=>{taskUid.value=typeof route.query.taskUid==='string'?route.query.taskUid:'';noteUid.value=typeof route.query.noteUid==='string'?route.query.noteUid:''})
onMounted(()=>{void prepareFocusTimer().catch(()=>{});window.addEventListener('focus',refresh);window.addEventListener('note-flow:profile-change',scopeChanged);window.addEventListener('note-flow:workspace-change',scopeChanged);void Promise.allSettled([tasks.load(),notes.load()]).then(()=>{if(!disposed&&(tasks.error||notes.error))metadataWarning.value='部分关联内容名称暂未加载，专注记录仍可查看。'})})
onBeforeUnmount(()=>{disposed=true;request++;window.removeEventListener('focus',refresh);window.removeEventListener('note-flow:profile-change',scopeChanged);window.removeEventListener('note-flow:workspace-change',scopeChanged)})
</script>
<template><main class="page focus-records-page"><section class="focus-auxiliary"><ElButton @click="router.push('/focus')">返回专注</ElButton><ElButton @click="router.push({path:'/settings',query:{tab:'focus'}})">专注设置</ElButton><ElSelect v-model="focusTimer.kind" aria-label="计时类型" :disabled="Boolean(focusTimer.session)" style="width:140px"><ElOption label="专注" value="focus"/><ElOption label="短休息" value="short_break"/><ElOption label="长休息" value="long_break"/></ElSelect><ElSelect v-model="focusTimer.taskUid" aria-label="本次专注关联任务" :disabled="Boolean(focusTimer.session)" clearable placeholder="不关联任务" style="width:220px"><ElOption v-for="task in taskOptions" :key="task.uid" :label="task.title||'未命名任务'" :value="task.uid"/></ElSelect></section><header class="focus-records-toolbar"><h1>专注记录</h1><div class="focus-range-shortcuts" role="group" aria-label="专注记录日期范围"><button @click="quickRange(1)">今天</button><button @click="quickRange(7)">近 7 天</button><button @click="quickRange(30)">近 30 天</button></div><button :disabled="loading" @click="load">{{loading?'刷新中…':'刷新'}}</button></header>
 <div class="focus-records-filters"><label>从<input v-model="from" type="date" aria-label="开始日期"/></label><label>至<input v-model="to" type="date" aria-label="结束日期"/></label><label>任务<select v-model="taskUid" aria-label="筛选关联任务"><option value="">全部任务</option><option v-if="taskUid&&!taskOptions.some(item=>item.uid===taskUid)" :value="taskUid">{{taskTitle(taskUid)}}</option><option v-for="task in taskOptions" :key="task.uid" :value="task.uid">{{task.title||'未命名任务'}}</option></select></label><label>类型<select v-model="kind" aria-label="筛选记录类型"><option value="all">全部记录</option><option value="focus">专注</option><option value="break">休息</option></select></label><span v-if="noteUid" class="focus-note-filter">笔记：{{noteTitle(noteUid)}} <button aria-label="清除笔记筛选" @click="noteUid=''">×</button></span></div>
 <p v-if="error" class="focus-records-error" role="alert">{{error}} <button @click="load">重试</button></p><p v-if="sourceWarning" class="focus-records-hint" role="status">{{sourceWarning}}</p><p v-if="metadataWarning" class="focus-records-hint">{{metadataWarning}}</p>
 <section class="focus-records-stats" aria-label="当前范围专注统计"><div><strong>{{Math.round(summary.totalSeconds/60)}}</strong><span>专注分钟</span></div><div><strong>{{summary.sessionCount}}</strong><span>完成次数</span></div><div><strong>{{summary.activeDays}}</strong><span>专注天数</span></div></section>
 <p class="focus-records-hint">统计仅计入已完成的专注，休息和中断记录单独保留。移动端记录同步后可在这里查看。</p>
 <p v-if="loading" class="focus-records-empty" role="status">正在加载专注记录…</p><p v-else-if="!error&&!filtered.length" class="focus-records-empty">当前范围内暂无专注记录。</p>
 <div v-else-if="!error" class="focus-records-table-wrap"><table class="focus-records-table"><thead><tr><th>开始时间</th><th>类型</th><th>实际时长</th><th>状态</th><th>关联内容</th><th></th></tr></thead><tbody><tr v-for="item in visible" :key="item.uid"><td>{{timestamp(item.startedAt)}}</td><td><span class="focus-type" :class="{break:item.sessionType!=='focus'}">{{typeLabel(item.sessionType)}}</span></td><td>{{focusDuration(item.actualSeconds)}}</td><td>{{statusLabel(item.status)}}<small v-if="item.overlapped" title="这条记录与其他专注时间重叠"> · 时间重叠</small></td><td class="focus-linked"><button v-if="item.taskUid" @click="openTask(item.taskUid)">{{taskTitle(item.taskUid)}}</button><button v-if="item.noteUid" @click="openNote(item.noteUid)">{{noteTitle(item.noteUid)}}</button><span v-if="!item.taskUid&&!item.noteUid">未关联</span></td><td><button @click="showDetail(item)">详情</button></td></tr></tbody></table><button v-if="filtered.length>limit" class="focus-load-more" @click="limit+=50">加载更多（已显示 {{visible.length}} / {{filtered.length}}）</button></div>
 <dialog ref="detailDialog" class="focus-record-detail" @close="detail=undefined"><template v-if="detail"><header><strong>专注记录详情</strong><button aria-label="关闭专注记录详情" @click="closeDetail">×</button></header><dl><div><dt>类型</dt><dd>{{typeLabel(detail.sessionType)}}</dd></div><div><dt>状态</dt><dd>{{statusLabel(detail.status)}}</dd></div><div><dt>开始</dt><dd>{{timestamp(detail.startedAt)}}</dd></div><div><dt>结束</dt><dd>{{timestamp(detail.endedAt)}}</dd></div><div><dt>计划时长</dt><dd>{{focusDuration(detail.plannedSeconds)}}</dd></div><div><dt>实际时长</dt><dd>{{focusDuration(detail.actualSeconds)}}</dd></div><div v-if="detail.taskUid"><dt>任务</dt><dd>{{taskTitle(detail.taskUid)}}</dd></div><div v-if="detail.noteUid"><dt>笔记</dt><dd>{{noteTitle(detail.noteUid)}}</dd></div></dl></template></dialog>
</main></template>
<style scoped>
.focus-auxiliary{display:flex;align-items:center;gap:12px;flex-wrap:wrap;margin-bottom:24px}

.focus-records-page{box-sizing:border-box;width:min(var(--pc-standard-width,1180px),100%);margin-inline:auto;padding-top:18px}.focus-records-toolbar{display:flex;align-items:center;gap:16px;flex-wrap:wrap;margin-bottom:14px}.focus-records-toolbar h1{margin:0;font-size:16px}.focus-range-shortcuts{display:flex;gap:4px;margin-left:auto}.focus-records-page button{padding:6px 10px;border:1px solid var(--pc-border);border-radius:6px;background:#fff;color:var(--pc-muted);font-size:11px;cursor:pointer}.focus-records-page button:hover{background:var(--pc-primary-soft);color:var(--pc-primary)}.focus-records-page button:disabled{opacity:.5;cursor:wait}.focus-records-filters{display:flex;align-items:center;gap:12px;flex-wrap:wrap;margin-bottom:16px}.focus-records-filters label{display:flex;align-items:center;gap:7px;color:var(--pc-muted);font-size:11px}.focus-records-filters input,.focus-records-filters select{min-width:0;padding:6px 8px;border:1px solid var(--pc-border);border-radius:6px;background:#fff;color:var(--pc-text);font-size:11px}.focus-records-filters select{max-width:240px}.focus-note-filter{color:var(--pc-muted);font-size:11px}.focus-records-stats{display:grid;grid-template-columns:repeat(3,1fr);gap:16px;padding:16px 0;border-block:1px solid var(--pc-border)}.focus-records-stats>div{display:flex;align-items:baseline;gap:10px}.focus-records-stats strong{font-size:24px;font-weight:650;color:var(--pc-text)}.focus-records-stats span,.focus-records-hint{color:var(--pc-muted);font-size:11px;line-height:1.7}.focus-records-error{padding:10px;color:#a3453b;background:#fff4f4}.focus-records-empty{padding:48px 12px;text-align:center;color:var(--pc-muted);font-size:12px}.focus-records-table-wrap{overflow:auto}.focus-records-table{width:100%;border-collapse:collapse;font-size:12px;text-align:left}.focus-records-table th{color:var(--pc-muted);font-weight:500}.focus-records-table th,.focus-records-table td{padding:12px 10px;border-bottom:1px solid var(--pc-border);white-space:nowrap}.focus-type{padding:3px 6px;border-radius:5px;background:var(--pc-primary-soft);color:var(--pc-primary)}.focus-type.break{background:#f0f2f3;color:#79828a}.focus-linked{max-width:280px}.focus-linked button{display:block;max-width:100%;overflow:hidden;text-overflow:ellipsis;margin:2px 0;border:0!important;padding:3px 0!important;color:var(--pc-primary)!important}.focus-load-more{display:block;margin:16px auto}.focus-record-detail{width:min(440px,calc(100% - 32px));padding:20px;border:1px solid var(--pc-border);border-radius:12px;color:var(--pc-text)}.focus-record-detail::backdrop{background:#0005}.focus-record-detail header{display:flex;justify-content:space-between;align-items:center}.focus-record-detail dl>div{display:flex;justify-content:space-between;gap:20px;padding:8px 0;font-size:12px}.focus-record-detail dt{flex:none;color:var(--pc-muted)}.focus-record-detail dd{margin:0;text-align:right;overflow-wrap:anywhere}@media(max-width:620px){.focus-records-page{padding:16px}.focus-records-stats>div{display:grid;gap:4px}.focus-records-filters label{max-width:100%}.focus-range-shortcuts{margin-left:0}}
</style>
